const grid = document.getElementById("productGrid");
const categoryList = document.getElementById("categoryList");
const searchInput = document.getElementById("search");
const searchBtn = document.querySelector(".search-row button");
const toast = document.getElementById("toast");

let cart = JSON.parse(localStorage.getItem("cart")) || [];
let selectedCategory = "all";

/* ---------- CATEGORIES ---------- */
function renderCategories() {
  const categories = ["all", ...new Set(products.map(p => p.category))];

  categoryList.innerHTML = categories.map(cat => `
    <li data-category="${cat}">
      ${cat}
      <span class="count">${
        cat === "all"
          ? products.length
          : products.filter(p => p.category === cat).length
      }</span>
    </li>
  `).join("");

  document.querySelectorAll("#categoryList li").forEach(li => {
    li.addEventListener("click", () => {
      document.querySelectorAll("#categoryList li").forEach(c => c.classList.remove("active"));
      li.classList.add("active");
      selectedCategory = li.dataset.category;
      filterProducts();
    });
  });
}

/* ---------- PRODUCTS ---------- */
function renderProducts(list) {
  grid.innerHTML = "";

  if (list.length === 0) {
    grid.innerHTML = "<p>No products found 😢</p>";
    return;
  }

  list.forEach(p => {
    grid.innerHTML += `
      <div class="product-card">
        <img src="${p.image}">
        <h3>${p.name}</h3>
        <p>₹${p.price}</p>
        
        <button onclick="addToCart(${p.id}, this)">Add to Cart</button>

      </div>
    `;
  });
}

/* ---------- FILTER ---------- */
function filterProducts() {
  let filtered = products.filter(p =>
    p.name.toLowerCase().includes(searchInput.value.toLowerCase())
  );

  if (selectedCategory !== "all") {
    filtered = filtered.filter(p => p.category === selectedCategory);
  }

  renderProducts(filtered);
}

