function addToCart(id, btn) {
  const product = products.find(p => p.id === id);
  const existing = cart.find(item => item.id === id);

  if (existing) existing.qty++;
  else cart.push({ ...product, qty: 1 });

  localStorage.setItem("cart", JSON.stringify(cart));
  updateCartCount();
  showToast(`${product.name} added to cart`);

  animateToCart(btn, product.image);
}


function updateCartCount() {
  const cartCount = document.getElementById("cart-count");
  cartCount.innerText = cart.reduce((sum, i) => sum + (i.qty || 1), 0);

  cartCount.classList.remove("cart-bounce");
  void cartCount.offsetWidth; // reset animation
  cartCount.classList.add("cart-bounce");
}

function animateToCart(button, imgSrc) {
  const cartIcon = document.querySelector(".cart");
  if (!cartIcon) return;

  const img = document.createElement("img");
  img.src = imgSrc;
  img.className = "fly-img";

  const btnRect = button.getBoundingClientRect();
  img.style.top = btnRect.top + "px";
  img.style.left = btnRect.left + "px";

  document.body.appendChild(img);

  const cartRect = cartIcon.getBoundingClientRect();

  setTimeout(() => {
    img.style.transform = `
      translate(${cartRect.left - btnRect.left}px,
                ${cartRect.top - btnRect.top}px)
      scale(0.1)
    `;
    img.style.opacity = "0";
  }, 10);

  setTimeout(() => img.remove(), 700);
}



/* ---------- INIT ---------- */
renderCategories();
renderProducts(products);
updateCartCount();

searchBtn.onclick = filterProducts;
searchInput.oninput = filterProducts;
